import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

const files = [
  "src/utils/Random.js",
  "src/utils/Color.js",
  "src/noise/Noise.js",
  "src/generators/GeneratorHelpers.js",
  "src/generators/TerrainGenerator.js",
  "src/generators/CloudGenerator.js",
  "src/generators/FogGenerator.js",
  "src/generators/LightningGenerator.js",
  "src/generators/PuddleGenerator.js",
  "src/generators/FireGenerator.js",
  "src/generators/ShieldGenerator.js",
  "src/generators/ExtendedGenerators.js",
  "src/generators/domains/MapGenerators.js",
  "src/generators/domains/MaterialGenerators.js",
  "src/generators/domains/WaterGenerators.js",
  "src/generators/domains/EnvironmentGenerators.js",
  "src/generators/domains/VfxGenerators.js",
  "src/generators/domains/ToolMapGenerators.js",
  "src/generators/GeneratorMetadata.js",
  "src/generators/index.js",
  "src/utils/OutputOptions.js",
  "src/utils/ImageExport.js",
  "src/core/I18n.js",
  "src/core/Registry.js",
  "src/core/ParamPanel.js",
  "src/core/PreviewController.js",
  "src/core/RenderWorkerClient.js",
  "src/core/App.js",
  "src/main.js",
];

const workerFiles = [
  "src/utils/Random.js",
  "src/utils/Color.js",
  "src/noise/Noise.js",
  "src/generators/GeneratorHelpers.js",
  "src/generators/TerrainGenerator.js",
  "src/generators/CloudGenerator.js",
  "src/generators/FogGenerator.js",
  "src/generators/LightningGenerator.js",
  "src/generators/PuddleGenerator.js",
  "src/generators/FireGenerator.js",
  "src/generators/ShieldGenerator.js",
  "src/generators/ExtendedGenerators.js",
  "src/generators/domains/MapGenerators.js",
  "src/generators/domains/MaterialGenerators.js",
  "src/generators/domains/WaterGenerators.js",
  "src/generators/domains/EnvironmentGenerators.js",
  "src/generators/domains/VfxGenerators.js",
  "src/generators/domains/ToolMapGenerators.js",
  "src/generators/GeneratorMetadata.js",
  "src/generators/index.js",
  "src/utils/OutputOptions.js",
];

function transform(source) {
  return source
    .replace(/^import\s+[^;]+;\s*$/gm, "")
    .replace(/^export\s+(?=(async\s+function|function|class|const|let|var)\s)/gm, "")
    .replace(/^export\s*\{[^}]+\};?\s*$/gm, "");
}

const body = files
  .map((file) => `\n// ${file}\n${transform(readFileSync(join(root, file), "utf8"))}`)
  .join("\n");

const workerBody = workerFiles
  .map((file) => `\n// ${file}\n${transform(readFileSync(join(root, file), "utf8"))}`)
  .join("\n");

const workerSource = `${workerBody}
self.onmessage = async (event) => {
  const { jobId, type, generatorId, params, width, height, time, output, mimeType, mapType } = event.data;
  try {
    const generator = generators.find((item) => item.id === generatorId);
    if (!generator) throw new Error("Unknown generator: " + generatorId);
    if (typeof OffscreenCanvas === "undefined") throw new Error("OffscreenCanvas is not available");
    const canvas = new OffscreenCanvas(width, height);
    generator.generate(canvas, params, { time, output, exporting: type === "export", mapType: mapType || "color", tileable: output && output.tileable });
    applyTileableBlend(canvas, output);
    applyOutputOptions(canvas, output);
    buildDerivedMap(canvas, mapType || "color", { generatorId });
    if (type === "export") {
      const blob = await canvas.convertToBlob({ type: mimeType || "image/png", quality: 0.94 });
      self.postMessage({ jobId, ok: true, result: blob });
    } else {
      const bitmap = canvas.transferToImageBitmap();
      self.postMessage({ jobId, ok: true, result: bitmap }, [bitmap]);
    }
  } catch (error) {
    self.postMessage({ jobId, ok: false, error: error && error.message ? error.message : String(error) });
  }
};
`;

const output = `// Generated by tools/build-bundle.mjs. Edit src modules, then rebuild.\n(() => {\n\"use strict\";\nwindow.__GTL_WORKER_SOURCE__ = ${JSON.stringify(workerSource)};\n${body}\n})();\n`;

writeFileSync(join(root, "src/app.bundle.js"), output, "utf8");
console.log("Wrote src/app.bundle.js");
